#include <iostream>
using namespace std;

// Change the caller's two integers, rather than local copies.
void exchange(int @1 a, int @2 b) {
    int temp = a;
    a = @3;
    b = @4;
}

// Add amount to the caller's balance. Default increase: 5.
void increase(double @5 balance, double amount = @6) {
    balance += amount;
}

// Return a fractional average even when both inputs are integers.
double average(int a, int b) {
    return @7 / 2;
}

int main() {
    int left = 3, right = 8;
    exchange(@8, right);
    double balance = 10;
    increase(balance);
    cout << left << ' ' << right << ' ' << balance << ' '
         << average(3, 8) << '\n';
}

#include <iostream>
using namespace std;

// Return a new array containing twice each input value.
// Caller owns the returned allocation.
@1 doubled(const double *values, int size) {
