    }
    return @5;
}

// Replace the number stored at the supplied address.
void replace(double *destination, double value) {
    @6 = value;
}

int main() {
    double readings[] = {1.5, 2.0, 4.0};
    double *copy = doubled(readings, 3);
    replace(@7, 9.0); // Replace only copy[1].
    cout << copy[0] << ' ' << copy[1] << ' ' << copy[2]
         << ' ' << readings[1] << '\n';
    delete @8;
    copy = @9;
}

#include <iostream>
using namespace std;

class Sensor {
    double reading;
public:
    Sensor();
    Sensor(double value);
    void set(double value);
    double get() const;
};

@1 Sensor() { reading = 0; }
@2 Sensor(double value) { reading = value; }
void @3 set(double value) { reading = value; }
double Sensor::get() @4 { return reading; }

// Update the object through its pointer.
void calibrate(Sensor *sensor, double offset) {
    sensor@5 set(sensor@6 get() + offset);
}

// Return one reading per sensor; caller must free the array.
double *readAll(const Sensor *sensors, int size) {
    double *values = @7;
    for (int i = 0; i < size; ++i) {
        values[i] = sensors[i]@8 get();
    }
    return values;
}

int main() {
    Sensor sensors[] = {Sensor(10), Sensor(20)};
    calibrate(@9, 2);
    double *values = readAll(sensors, 2);
    cout << values[0] << ' ' << values[1] << '\n';
    delete @10;
}

