// Change an existing box through a reference.
void reshape(Box @7 box, const double *dimensions) {
    box.@8(dimensions);
}

// Caller owns the returned array of volumes.
double *volumes(const Box *boxes, int size) {
    double *results = @9;
    for (int i = 0; i < size; ++i) {
        results[i] = @10;
    }
