int main() {
    Box *boxes = new Box[2];
    double dimensions[] = {2, 3, 4};
    reshape(boxes[1], dimensions);
    double *values = volumes(boxes, 2);
    double *copiedDimensions = boxes[1].getDimensions();
    cout << values[0] << ' ' << values[1] << ' '
         << copiedDimensions[2] << '\n';
