#include <iostream>
#include <fstream>
using namespace std;

int main() {
    @1 output("readings.txt");
    if (!output) return 1;
    output @2 2.5 << ' ' << 4.0 << ' ' << 1.5;
    output.@3(); // Finish writing before opening for reading.

    @4 input("readings.txt");
    if (!input) return 1;
    double value = 0, total = 0;
    int count = 0;
    while (@5) {
        total @6 value;
        ++count;
    }
    // A failed extraction is expected at EOF, but not elsewhere.
    if (input.bad() || !input.@7()) return 2;
    cout << total << ' ' << count << '\n';
}

#include <iostream>
#include <stdexcept>
using namespace std;

double average(double total, int count) {
    if (count <= 0) {
        @1 invalid_argument("count must be positive");
    }
    return total @2 count;
}

int main() {
    @3 {
        cout << average(9, 2) << '\n';
        double result = average(9, 0);
        cout << result << '\n'; // Skipped after the exception.
    } @4 (const invalid_argument @5 error) {
        cout << error.@6() << '\n';
    }
    cout << "continues" << '\n';
}
